return [
  {
    json: {
      tasks: [
        {
          type: 'math',
          question: 'Solve x^2 + 5x + 6 = 0'
        },
        {
          type: 'english',
          question: 'Correct this sentence: he go to school'
        },
        {
          type: 'coding',
          question: 'Write Python code for fibonacci'
        }
      ]
    }
  }
];

const tasks = $json.tasks;

return tasks.map((task, index) => {
  return {
    json: {
      taskId: index + 1,
      taskType: task.type,
      question: task.question,
      allTasks: tasks
    }
  };
});

const memory = $getWorkflowStaticData('global');

if (!memory.results) {
  memory.results = [];
}

const previousOutputs = memory.results;

const dynamicPrompt = `
You are an advanced universal AI agent capable of solving ANY type of problem dynamically.

========================
CURRENT TASK
========================
Task ID: ${$json.taskId}
Task Type: ${$json.taskType}
Question: ${$json.question}

========================
ALL TASKS PROVIDED
========================
${JSON.stringify($json.allTasks, null, 2)}

========================
PREVIOUS TASK OUTPUTS
========================
${JSON.stringify(previousOutputs, null, 2)}

========================
INSTRUCTIONS
========================
1. Analyze the task type dynamically.
2. Solve the problem professionally.
3. If task is math:
   - Solve step-by-step.
   - Explain formulas.
4. If task is english:
   - Correct grammar.
   - Improve sentence quality.
5. If task is coding:
   - Generate clean production-ready code.
   - Add explanation.
6. You may use previous task outputs for context.
7. Maintain high accuracy.
8. Return ONLY valid JSON.
9. Never return markdown.
10. Never return code blocks.

========================
OUTPUT FORMAT
========================
{
  "taskId": "${$json.taskId}",
  "taskType": "${$json.taskType}",
  "question": "${$json.question}",
  "solution": "Detailed solution here",
  "summary": "Short summary",
  "difficulty": "easy/medium/hard",
  "qualityScore": 95
}
`;

return [
  {
    json: {
      taskId: $json.taskId,
      taskType: $json.taskType,
      question: $json.question,
      prompt: dynamicPrompt
    }
  }
];

const memory = $getWorkflowStaticData('global');

if (!memory.results) {
  memory.results = [];
}

const result = $json.output || $json;

memory.results.push(result);

return [
  {
    json: $json
  }
];

const memory = $getWorkflowStaticData('global');

return [
  {
    json: {
      status: "All Tasks Processed Successfully",
      totalTasks: memory.results?.length || 0,
      completedTasks: memory.results || []
    }
  }
];
